float copysignf(float x, float s) {
    uint uabs = floatBitsToUint(x) & 0x7fffffffU;
    uint usig = floatBitsToUint(s) & 0x80000000U;
    return uintBitsToFloat(uabs | usig);
}

// given by https://www.shadertoy.com/user/mla
float mulsignf(float x, float s) {
    uint u = floatBitsToUint(s) & 0x80000000U;
    u ^= floatBitsToUint(x);
    return uintBitsToFloat(u);
}

float signed1(float x) {
    return copysignf(1.0, x);
}

float signed2(float x) {
    return x >= 0.0 ? 1.0 : -1.0;
}

float signed3(float x) {
    return sign(sign(x) + 0.5);
}

float signed4(float x) {
    return float(x >= 0.0) - float(x < 0.0);
}

float signed5(float x) {
    float t = float(x >= 0.0);
    return float(t + t - 1.0);
}

float signed6(float x) {
    uint ix = (floatBitsToUint(x) & 0x80000000U);
    ix |= 0x3f800000U;
    return uintBitsToFloat(ix);
}

float signed7(float x) {
    return mulsignf(1.0, x);
}

float run(float x) {
    return float(signed7(x - 0.5) == sign(sin(iTime * 5.0)));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord / iResolution.xy;

    vec3 col;

    uv -= 0.5;
    uv *= 5.0;
    col = vec3(run(max(floor(abs(uv.x)), floor(abs(uv.y)))));

    fragColor = vec4(col, 1.0);
}
